<?php

namespace App\Support\QrCode;

use InvalidArgumentException;

/**
 * Small QR encoder for byte-mode URLs. It supports QR versions 1-L through 5-L,
 * which is sufficient for the attendance links generated by this application.
 */
class QrCodeSvg
{
    /** @var array<int, array{0:int,1:int}> version => [data codewords, error correction codewords] */
    private const CAPACITIES = [
        1 => [19, 7],
        2 => [34, 10],
        3 => [55, 15],
        4 => [80, 20],
        5 => [108, 26],
    ];

    public static function render(string $content): string
    {
        $bytes = array_values(unpack('C*', $content) ?: []);
        $version = self::selectVersion(count($bytes));
        [$dataCodewords, $eccCodewords] = self::CAPACITIES[$version];
        $codewords = self::createCodewords($bytes, $dataCodewords, $eccCodewords);
        $matrix = self::createMatrix($version, $codewords);

        return self::toSvg($matrix);
    }

    private static function selectVersion(int $byteLength): int
    {
        foreach (self::CAPACITIES as $version => [$dataCodewords]) {
            $capacityBits = $dataCodewords * 8;
            $requiredBits = 4 + 8 + ($byteLength * 8);
            if ($requiredBits <= $capacityBits) {
                return $version;
            }
        }

        throw new InvalidArgumentException('URL absensi terlalu panjang untuk QR Code yang didukung.');
    }

    /** @param array<int, int> $bytes
     *  @return array<int, int>
     */
    private static function createCodewords(array $bytes, int $dataLength, int $eccLength): array
    {
        $capacityBits = $dataLength * 8;
        $bits = [];
        self::appendBits($bits, 0b0100, 4);
        self::appendBits($bits, count($bytes), 8);

        foreach ($bytes as $byte) {
            self::appendBits($bits, $byte, 8);
        }

        $terminatorLength = min(4, $capacityBits - count($bits));
        for ($index = 0; $index < $terminatorLength; $index++) {
            $bits[] = 0;
        }

        while (count($bits) % 8 !== 0) {
            $bits[] = 0;
        }

        $data = [];
        for ($offset = 0; $offset < count($bits); $offset += 8) {
            $value = 0;
            for ($bit = 0; $bit < 8; $bit++) {
                $value = ($value << 1) | $bits[$offset + $bit];
            }
            $data[] = $value;
        }

        $pad = 0;
        while (count($data) < $dataLength) {
            $data[] = $pad % 2 === 0 ? 0xEC : 0x11;
            $pad++;
        }

        return [...$data, ...self::reedSolomonRemainder($data, $eccLength)];
    }

    /** @param array<int, int> $bits */
    private static function appendBits(array &$bits, int $value, int $length): void
    {
        for ($index = $length - 1; $index >= 0; $index--) {
            $bits[] = ($value >> $index) & 1;
        }
    }

    /** @param array<int, int> $data
     *  @return array<int, int>
     */
    private static function reedSolomonRemainder(array $data, int $degree): array
    {
        $divisor = [1];
        for ($index = 0; $index < $degree; $index++) {
            $next = array_fill(0, count($divisor) + 1, 0);
            $root = self::gfPower($index);
            foreach ($divisor as $position => $coefficient) {
                $next[$position] ^= $coefficient;
                $next[$position + 1] ^= self::gfMultiply($coefficient, $root);
            }
            $divisor = $next;
        }

        $remainder = array_fill(0, $degree, 0);
        foreach ($data as $byte) {
            $factor = $byte ^ $remainder[0];
            array_shift($remainder);
            $remainder[] = 0;

            for ($index = 0; $index < $degree; $index++) {
                $remainder[$index] ^= self::gfMultiply($divisor[$index + 1], $factor);
            }
        }

        return $remainder;
    }

    private static function gfPower(int $exponent): int
    {
        $value = 1;
        for ($index = 0; $index < $exponent; $index++) {
            $value = self::gfMultiply($value, 2);
        }

        return $value;
    }

    private static function gfMultiply(int $x, int $y): int
    {
        $result = 0;
        while ($y > 0) {
            if (($y & 1) !== 0) {
                $result ^= $x;
            }
            $y >>= 1;
            $x <<= 1;
            if (($x & 0x100) !== 0) {
                $x ^= 0x11D;
            }
        }

        return $result;
    }

    /** @param array<int, int> $codewords
     *  @return array<int, array<int, bool>>
     */
    private static function createMatrix(int $version, array $codewords): array
    {
        $size = 17 + ($version * 4);
        $matrix = array_fill(0, $size, array_fill(0, $size, false));
        $function = array_fill(0, $size, array_fill(0, $size, false));

        $setFunction = static function (int $row, int $column, bool $value) use (&$matrix, &$function, $size): void {
            if ($row < 0 || $column < 0 || $row >= $size || $column >= $size) {
                return;
            }
            $matrix[$row][$column] = $value;
            $function[$row][$column] = true;
        };

        foreach ([[0, 0], [0, $size - 7], [$size - 7, 0]] as [$top, $left]) {
            for ($dy = -1; $dy <= 7; $dy++) {
                for ($dx = -1; $dx <= 7; $dx++) {
                    $row = $top + $dy;
                    $column = $left + $dx;
                    if ($row < 0 || $column < 0 || $row >= $size || $column >= $size) {
                        continue;
                    }

                    $inside = $dy >= 0 && $dy <= 6 && $dx >= 0 && $dx <= 6;
                    $distance = max(abs($dx - 3), abs($dy - 3));
                    $setFunction($row, $column, $inside && $distance !== 2);
                }
            }
        }

        for ($index = 8; $index < $size - 8; $index++) {
            $setFunction(6, $index, $index % 2 === 0);
            $setFunction($index, 6, $index % 2 === 0);
        }

        $alignmentPositions = match ($version) {
            2 => [6, 18],
            3 => [6, 22],
            4 => [6, 26],
            5 => [6, 30],
            default => [],
        };

        foreach ($alignmentPositions as $centerRow) {
            foreach ($alignmentPositions as $centerColumn) {
                if ($function[$centerRow][$centerColumn]) {
                    continue;
                }

                for ($dy = -2; $dy <= 2; $dy++) {
                    for ($dx = -2; $dx <= 2; $dx++) {
                        $distance = max(abs($dx), abs($dy));
                        $setFunction($centerRow + $dy, $centerColumn + $dx, $distance !== 1);
                    }
                }
            }
        }

        self::drawFormatInformation($setFunction, $size);

        $dataBits = [];
        foreach ($codewords as $codeword) {
            self::appendBits($dataBits, $codeword, 8);
        }

        $bitIndex = 0;
        $upward = true;
        for ($right = $size - 1; $right >= 1; $right -= 2) {
            if ($right === 6) {
                $right = 5;
            }

            for ($vertical = 0; $vertical < $size; $vertical++) {
                $row = $upward ? $size - 1 - $vertical : $vertical;

                for ($offset = 0; $offset < 2; $offset++) {
                    $column = $right - $offset;
                    if ($function[$row][$column]) {
                        continue;
                    }

                    $bit = $dataBits[$bitIndex] ?? 0;
                    $bitIndex++;
                    if (($row + $column) % 2 === 0) {
                        $bit ^= 1;
                    }
                    $matrix[$row][$column] = $bit === 1;
                }
            }

            $upward = !$upward;
        }

        return $matrix;
    }

    /** @param callable(int, int, bool): void $setFunction */
    private static function drawFormatInformation(callable $setFunction, int $size): void
    {
        // Error correction level L has format bits 01. Mask pattern 0 is valid
        // and keeps this compact encoder deterministic.
        $data = (0b01 << 3);
        $remainder = $data << 10;
        for ($index = 14; $index >= 10; $index--) {
            if ((($remainder >> $index) & 1) !== 0) {
                $remainder ^= 0x537 << ($index - 10);
            }
        }
        $bits = (($data << 10) | $remainder) ^ 0x5412;

        for ($index = 0; $index <= 5; $index++) {
            $setFunction($index, 8, (($bits >> $index) & 1) !== 0);
        }
        $setFunction(7, 8, (($bits >> 6) & 1) !== 0);
        $setFunction(8, 8, (($bits >> 7) & 1) !== 0);
        $setFunction(8, 7, (($bits >> 8) & 1) !== 0);
        for ($index = 9; $index < 15; $index++) {
            $setFunction(8, 14 - $index, (($bits >> $index) & 1) !== 0);
        }

        for ($index = 0; $index < 8; $index++) {
            $setFunction(8, $size - 1 - $index, (($bits >> $index) & 1) !== 0);
        }
        for ($index = 8; $index < 15; $index++) {
            $setFunction($size - 15 + $index, 8, (($bits >> $index) & 1) !== 0);
        }
        $setFunction($size - 8, 8, true);
    }

    /** @param array<int, array<int, bool>> $matrix */
    private static function toSvg(array $matrix): string
    {
        $size = count($matrix);
        $quietZone = 4;
        $viewSize = $size + ($quietZone * 2);
        $path = [];

        foreach ($matrix as $row => $columns) {
            foreach ($columns as $column => $isDark) {
                if ($isDark) {
                    $x = $column + $quietZone;
                    $y = $row + $quietZone;
                    $path[] = 'M'.$x.' '.$y.'h1v1h-1z';
                }
            }
        }

        return '<svg xmlns="http://www.w3.org/2000/svg" width="240" height="240" viewBox="0 0 '.$viewSize.' '.$viewSize.'" role="img" aria-label="QR Code absensi" shape-rendering="crispEdges">'
            .'<rect width="100%" height="100%" fill="#fff"/>'
            .'<path d="'.implode('', $path).'" fill="#111827"/>'
            .'</svg>';
    }
}
